"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[60469],{90870(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>o,default:()=>p,frontMatter:()=>a,metadata:()=>s,toc:()=>d});const s=JSON.parse('{"id":"general/running-winget-as-system-with-jumpcloud-commands-winget-upgrade","title":"Running Winget As System With Jumpcloud Commands Winget Upgrade","description":"By JacobLawson","source":"@site/docs/general/running-winget-as-system-with-jumpcloud-commands-winget-upgrade.md","sourceDirName":"general","slug":"/general/running-winget-as-system-with-jumpcloud-commands-winget-upgrade","permalink":"/jc-community-archive/general/running-winget-as-system-with-jumpcloud-commands-winget-upgrade","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Running Winget As System With Jumpcloud Commands Winget Upgrade","description":"By JacobLawson"},"sidebar":"docs","previous":{"title":"Run Command Every Time Macs Computer Go To Sleep Mode Wake Up Or","permalink":"/jc-community-archive/general/run-command-every-time-macs-computer-go-to-sleep-mode-wake-up-or"},"next":{"title":"Saas Management For Msps","permalink":"/jc-community-archive/general/saas-management-for-msps"}}');var i=n(74848),r=n(28453);const a={title:"Running Winget As System With Jumpcloud Commands Winget Upgrade",description:"By JacobLawson"},o=void 0,c={},d=[];function l(e){const t={a:"a",code:"code",em:"em",p:"p",pre:"pre",strong:"strong",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:["I've done some experimenting with automating software installs using powershell and winget.\xa0 As many of you know, one of the primary blockers to winget is the fact that it runs in the user session.\xa0 After a few hours of reading discussions on github, I came across\xa0",(0,i.jsx)(t.a,{href:"https://github.com/microsoft/winget-cli/discussions/962",children:"this thread"}),"\xa0with a promising approach from\xa0rothgecw\xa0to running winget as system.\xa0 This opened up a world of possibility!"]}),"\n",(0,i.jsx)(t.p,{children:"In my testing I discovered that when winget upgrades, the old directory in C:\\Program Files\\WindowsApps isn't always deleted so I needed a way to find the most up to date version of winget in the WindowsApps folder.\xa0 Hence the first part of the script below.\xa0 I start by finding the directory winget is installed in, if there are multiple versions, I sort the directories by path and save the last path as a variable.\xa0 From there I write the output of the variable to the console for sanity and troubleshooting purposes so I can see the directory in the command results from within the JumpCloud admin console.\xa0 Then I cd to that directory and we are ready to start using winget as system."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:"Note: winget must be installed for this to work."})}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{children:'#Powershell script that checks if apps are installed and installs them if they aren\'t\n\n#Query for directory most updated winget.exe is stored in\n$wingetdir = (Resolve-Path "C:\\Program Files\\WindowsApps\\Microsoft.DesktopAppInstaller_*_x64__8wekyb3d8bbwe" | Sort-Object -Property Path | Select-Object -Last 1)\n#Output directory\nWrite-Host "cd to directory: $wingetdir"\n#navigate to directory containing winget.exe\ncd $wingetdir\n'})}),"\n",(0,i.jsxs)(t.p,{children:["After navigating to the correct directory, we can pass commands to winget.\xa0\xa0Below is an example of a powershell script that installs Adobe Acrobat Reader on a system if it isn't already installed.\xa0 I start by searching the device for the software using winget list.\xa0 Then I use an if statement to determine whether or not the software needs installed.\xa0 If the software does need installed, I pass the following command to winget for a silent install of Adobe Acrobat Reader:\xa0",(0,i.jsx)(t.em,{children:"winget install --id 'Adobe.Acrobat.Reader.64-bit' --silent --accept-package-agreements --accept-source-agreements."})]}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{children:"#Variable containing results of search for app on the system\n$AdobeReader = (.\\winget.exe list --id 'Adobe.Acrobat.Reader.64-bit')\n#If statement to install app or move on\nIf ($AdobeReader -like '*No installed package found*')\n{\n    .\\winget.exe install --id 'Adobe.Acrobat.Reader.64-bit' --silent --accept-package-agreements --accept-source-agreements\n}\nelse\n{\n    Write-Host 'Adobe Reader is already installed.'\n}\n"})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"All together:"})}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{children:"#Script that checks if apps are installed and installs them if they aren't\n\n#Query for directory most updated winget.exe is stored in\n$wingetdir = (Resolve-Path \"C:\\Program Files\\WindowsApps\\Microsoft.DesktopAppInstaller_*_x64__8wekyb3d8bbwe\" | Sort-Object -Property Path | Select-Object -Last 1)\n#Output directory\nWrite-Host \"cd to directory: $wingetdir\"\n#navigate to directory containing winget.exe\ncd $wingetdir\n\n#Variable containing results of search for app on the system\n$AdobeReader = (.\\winget.exe list --id 'Adobe.Acrobat.Reader.64-bit')\n#If statement to install app or move on\nIf ($AdobeReader -like '*No installed package found*')\n{\n    .\\winget.exe install --id 'Adobe.Acrobat.Reader.64-bit' --silent --accept-package-agreements --accept-source-agreements\n}\nelse\n{\n    Write-Host 'Adobe Reader is already installed.'\n}\n"})}),"\n",(0,i.jsxs)(t.p,{children:["Winget has a very helpful feature that allows users to update all of their apps with a single command: ",(0,i.jsx)(t.em,{children:"winget upgrade --all"})]}),"\n",(0,i.jsx)(t.p,{children:"To make use of this, I have a JumpCloud command that creates a scheduled task on the users machine and moves a script to a desired directory to be ran at each user login."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:"Full disclosure: we aren't using this portion below in production yet, we are currently testing the user experience."})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Script containing winget upgrade --all command:"})}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{children:'#Query for directory most updated winget.exe is stored in\n$wingetdir = (Resolve-Path "C:\\Program Files\\WindowsApps\\Microsoft.DesktopAppInstaller_*_x64__8wekyb3d8bbwe" | Sort-Object -Property Path | Select-Object -Last 1)\n#Output directory\nWrite-Host "cd to directory: $wingetdir"\n#navigate to directory containing winget.exe\ncd $wingetdir\n\n#Command to update all apps with updates available. | Outfile is optional but I find it helpful for knowing the script ran on login. \n.\\winget.exe upgrade --all --silent --accept-package-agreements --accept-source-agreements | Out-File -FilePath \'C:\\Path\\To\\CommandResults.txt\' -Force\n'})}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.strong,{children:"Script that creates the scheduled task to run the above script on each user login as system:"})}),"\n",(0,i.jsx)(t.pre,{children:(0,i.jsx)(t.code,{children:"#Move the Winget Upgrade script to the desired directory here.\n#Once the script is in the correct directory, create the scheduled task. \n    #Create Task to run at logon\n    echo 'Creating scheduled task'\n    #Create variables needed for the task\n    $action = New-ScheduledTaskAction -Execute \"C:\\Windows\\System32\\WindowsPowershell\\v1.0\\powershell.exe\" -Argument '-ExecutionPolicy Bypass -File \"C:\\Path\\To\\WingetUpgrade.ps1\"'\n    $trigger = New-ScheduledTaskTrigger -AtLogon\n    $principal = New-ScheduledTaskPrincipal -UserID \"NT AUTHORITY\\SYSTEM\" -LogonType ServiceAccount -RunLevel Highest\n    $settings = New-ScheduledTaskSettingsSet\n    $description = 'runs: winget upgrade --all --silent --accept-package-agreemments --accept-source-agreements at logon to keep applications up to date.'\n    #Create the Task\n    $task = New-ScheduledTask -Action $action -Principal $principal -Trigger $trigger -Settings $settings -Description $description\n    #Register the Task\n    Register-ScheduledTask WingetUpgrade -InputObject $task\n    #Enable the task\n    Enable-ScheduledTask -TaskName \"WingetUpgrade\"  \n    #Test task was created\n    $TestTask = (Get-ScheduledTask -TaskName 'WingetUpgrade')\n    echo 'Outputting result of task creation'\n    Write-Host $TestTask\n}\n"})})]})}function p(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>o});var s=n(96540);const i={},r=s.createContext(i);function a(e){const t=s.useContext(r);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),s.createElement(r.Provider,{value:t},e.children)}}}]);